     *     the operation may already have changed state; do not retry automatically.
     * @see https://api.docs.cpanel.net/specifications/cpanel.openapi/wpx/wpx-import_website
     */
    public function importWebsite(
        #[SensitiveParameter]
        string $sourceUrl,
        #[SensitiveParameter]
        string $sourceUser,
        #[SensitiveParameter]
        string $sourcePassword,
        string $domain,
        ?bool $overwrite = null,
        #[SensitiveParameter]
        ?string $passwordType = null,
    ): array {
        /** @var ImportWebsiteResult $result Validated against WpxSpec::IMPORT_WEBSITE. */
        $result = ($this->run)(WpxSpec::IMPORT_WEBSITE, [
            'sourceUrl' => $sourceUrl,
            'sourceUser' => $sourceUser,
            'sourcePassword' => $sourcePassword,
            'domain' => $domain,
            'overwrite' => $overwrite,
            'passwordType' => $passwordType,
        ]);

        return $result;
    }

